NAME = 'ACV: A Conservative Version'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Peter, apostol Jezusa Kristusa, izvoljenim tujcem, razkropljenim po Pontu, Galaciji, Kapadociji, Aziji in Bitiniji,',
        2: 'izvoljenim po previdnosti Boga Očeta, v posvečenju Duha, k pokorščini in pokropljenju s krvjo Jezusa Kristusa: Milost vam in mir naj se pomnoži!',
        3: 'Hvaljen bodi Bog in Oče Gospoda našega Jezusa Kristusa, ki nas je po obilem usmiljenju svojem prerodil v živo upanje po vstajenju Jezusa Kristusa iz mrtvih,',
        4: 'v prejem dediščine neminljive in neoskrunjene in nevenljive, shranjene v nebesih za vas,',
        5: 'ki vas moč Božja čuva in po veri ohrani za zveličanje, pripravljeno, da se razodene v poslednjem času.',
        6: 'V katerem se radujete, čeprav ste ravnokar nekaj časa (ako je treba) v žalosti po mnogoterih izkušnjavah,',
        7: 'da se preizkušnja vere vaše, vrednejša nego preizkušnja minljivega, a v ognju izkušenega zlata, izkaže vam v hvalo in čast in slavo pri razodetju Jezusa Kristusa;',
        8: 'ki ga ljubite, dasi ga niste videli, ki ga sedaj ne gledate, a vendar vanj verujete in se v njem radujete z veseljem neizrečnim in polnim slave,',
        9: 'prejemajoč konec vere svoje, zveličanje duš.',
        10: 'O katerem zveličanju so preiskavali in ga izsledovali proroki, ki so prorokovali o milosti vam namenjeni,',
        11: 'preiskujoč, za kateri in za kakšen čas je oznanjal Duh Kristusov, ki je bil v njih in je najprej pričal za trpljenja Kristusova in veliko jim sledečo slavo.',
        12: 'Njim se je razodelo, da tistega niso podajali sebi, ampak vam, kar se vam je sedaj oznanilo po njih, ki so vam propovedovali evangelij v svetem Duhu, poslanem iz nebes; v kar angeli žele gledati.',
        13: 'Zato opašite ledja razuma svojega, bodite trezni in stavite svoje upanje popolnoma na milost, ki se vam prinaša v razodetju Jezusa Kristusa;',
        14: 'kakor otroci pokorščine se ne ravnajte po prejšnjih željah v času nevednosti svoje,',
        15: 'marveč po Svetem, ki vas je poklical, bodite tudi vi sveti v vsem svojem vedenju,',
        16: 'kajti pisano je: „Sveti bodite, ker sem jaz svet“.',
        17: 'In če Očeta kličete njega, ki sodi brez licegledja slehernega po njegovem delu, živite v strahu ves čas tujčevanja svojega,',
        18: 'vedoč, da niste odkupljeni z minljivimi rečmi, s srebrom ali zlatom, iz praznega življenja svojega, podedovanega od očetov,',
        19: 'ampak z drago krvjo kakor jagnjeta brez hibe in brez madeža, Kristusa;',
        20: 'ki je bil naprej spoznan pred ustanovitvijo sveta, razodel se je pa ob koncu časov zaradi vas,',
        21: 'ki po njem verujete v Boga, ki ga je obudil iz mrtvih in mu dal slavo, tako da je vera vaša tudi upanje v Boga.',
        22: 'Ker ste očistili duše svoje v pokorščini resnice za nehlinjeno bratoljubje, ljubite se iz čistega srca med seboj iskreno,',
        23: 'ker ste prerojeni ne iz minljivega semena, ampak neminljivega, po besedi Božji, ki živi in večno ostane.',
        24: 'Kajti „vse meso je kakor trava in vsa slava njegova kakor trave cvet; posuši se trava in cvet ji odpade,',
        25: 'beseda Gospodova pa ostane vekomaj“. To pa je beseda blagovestja, ki se vam je oznanila.',
    },
    2: {
        1: 'Odloživši torej vso hudobnost in vso zvijačnost in licemerstvo in zavist in vse obrekovanje,',
        2: 'hrepenite kakor novorojena deteta po nepokvarjenem mleku iz besede Božje, da po njem rastete v zveličanje,',
        3: 'če ste res okusili, da je Gospod dobrotljiv.',
        4: 'K njemu pristopajoč, kamenu živemu, ki so ga sicer zavrgli ljudje, pri Bogu pa je izvoljen in dragocen,',
        5: 'se sezidavate tudi vi kot živi kameni v hišo duhovno, sveto duhovništvo, da darujete duhovne daritve, prijetne Bogu po Jezusu Kristusu.',
        6: 'Kajti pisano je v pismu: „Glej, polagam na Sionu vogelni kamen, izvoljen, dragocen, in kdor veruje vanj, ne bo osramočen“.',
        7: 'Vam torej, ki verujete, je čast; nevernim pa je „ta kamen, ki so ga zavrgli zidarji, postal za glavo voglu“',
        8: 'in „kamen spotike in skala pohujšanja“; kateri se, ker so nepokorni besedi, spotikajo, za kar so bili tudi postavljeni.',
        9: 'Vi pa ste rod izvoljeni, kraljevsko duhovništvo, svet narod, ljudstvo Bogu za last, da oznanjate kreposti njega, ki vas je poklical iz teme v čudovito svetlobo svojo;',
        10: 'ki nekdaj niste bili ljudstvo, sedaj pa ste ljudstvo Božje, nekdaj ne deležni milosti, sedaj pa pomiloščeni.',
        11: 'Ljubljeni, opominjam vas kot tujce in popotnike, da se zdržujete mesenih poželenj, ki se vojskujejo zoper dušo;',
        12: 'vedenje vaše med pogani bodi lepo, da bodo v tem, v čemer vas obrekujejo kakor hudodelnike, slavili zaradi vaših dobrih del, ki jih vidijo, Boga v dan obiskovanja.',
        13: 'Pokorite se vsaki naredbi človeški zavoljo Gospoda: bodisi kralju kakor najvišjemu,',
        14: 'bodisi poglavarjem kakor od njega poslanim v kaznovanje hudodelnikov in v pohvalo teh, ki delajo dobro.',
        15: 'Kajti taka je volja Božja, da z dobrimi deli zavežite jezik nevednosti nespametnih ljudi;',
        16: 'kakor svobodni, a ne za pokrivalo hudobnosti imajoč svobodo, temveč kakor hlapci Božji.',
        17: 'Vse spoštujte, bratovščino ljubite, Boga se bojte, kralja častite!',
        18: 'Hlapci, bodite pokorni v vsem strahu gospodarjem, ne samo dobrim in krotkim, ampak tudi osornim.',
        19: 'Kajti to je milost, ako kdo iz vestnosti do Boga prenaša težave, po krivem trpeč.',
        20: 'Kakšna namreč hvala, če boste grešeč in zato tepeni trpeli? Ampak če ste, dobro delajoč in pri tem trpeč, stanovitni, to je prijetno pri Bogu.',
        21: 'Kajti za to ste bili poklicani, ker je tudi Kristus trpel za vas in vam zapustil zgled, da hodite po sledovih njegovih:',
        22: 'on ni storil greha, tudi zvijača se ni našla v ustih njegovih;',
        23: 'on psovan ni psoval, trpeč ni pretil, temuč vse je prepuščal tistemu, ki sodi pravično;',
        24: 'on je grehe naše sam na telesu svojem nesel na les, da bi grehom odmrli in živeli pravičnosti; ž njegovimi ranami ste bili ozdravljeni.',
        25: 'Bili ste namreč kakor ovce tavajoče, ali povrnili ste se zdaj k Pastirju in Škofu duš svojih.',
    },
    3: {
        1: 'Enako žene, pokorne bodite svojim možem, da jih, če kateri niso poslušni besedi, pridobite s svojim vedenjem brez besede,',
        2: 'ko vidijo bogaboječe in čisto življenje vaše.',
        3: 'Lepotičje vaše ne bodi vnanje, spletanje las in obešanje zlatnine ali oblačenje kril,',
        4: 'ampak skriti človek srca, v neminljivem krasu krotkega in mirnega duha, ki je dragocen pred Bogom.',
        5: 'Tako namreč so se nekdaj dičile tudi svete žene, ki so upale v Boga, podložne svojim možem;',
        6: 'kakor je bila Sara poslušna Abrahamu, imenujoč ga gospoda; njene hčerke ste postale ve, če delate dobro in se ne bojite nobenega strahu.',
        7: 'Možje takisto, živite z ženami svojimi po spoznanju, kakor s slabšo posodo, in jim dajajte čast, ker so tudi sodednice milosti življenja, da nimajo zaprek molitve vaše.',
        8: 'Slednjič pa, vsi bodite enega mišljenja, sočutni, bratoljubni, milosrčni, ponižni;',
        9: 'ne vračajte hudega za hudo ali psovanja za psovanje, ampak rajši blagoslavljajte, kajti za to ste poklicani, da podedujete blagoslov.',
        10: 'Zakaj „kdor hoče življenje ljubiti in videti dobre dni, brzda naj jezik pred hudim in ustne svoje, da ne govoré zvijače;',
        11: 'ogiblje se naj hudega in dela dobro; išče naj mirú in hodi za njim“.',
        12: 'Ker „oči Gospodove so obrnjene v pravične in ušesa njegova k njih molitvam, obličje Gospodovo pa zoper nje, ki delajo hudo“.',
        13: 'In kdo je, da bi vam kaj hudega storil, ako bodete vneti za dobro?',
        14: 'Ali ko bi tudi trpeli za pravičnost, blagor vam. Ne bojte pa se jih in se ne plašite,',
        15: 'Kristusa pa kot Gospoda posvečujte v srcih svojih. Pripravljeni bodite vsekdar na odgovor vsakemu, ki vas vpraša za vzroke upanja, ki je v vas, toda s krotkostjo in strahom.',
        16: 'In dobro vest imejte, da se v tem, za kar vas obrekujejo, osramote tisti, ki grdijo vaše lepo vedenje v Kristusu.',
        17: 'Bolje namreč, da trpite, če hoče volja Božja, pri dobrih delih nego pri hudih.',
        18: 'Ker tudi Kristus je enkrat trpel za grehe, pravični za krivične, da nas pripelje Bogu, usmrčen v mesu, oživljen pa v duhu;',
        19: 'v katerem je tudi šel in oznanjal duhovom v ječi,',
        20: 'ki so bili nekdaj neposlušni, ko je potrpežljivost Božja čakala v dneh Noetovih, ko se je napravljala barka, ki se je v njej malo, to je osem duš na varno rešilo po vodi;',
        21: 'temu podoben tudi vas zdaj rešuje krst, ne umitje mesene nesnage, ampak zaupljivo sklicevanje dobre vesti na Boga po vstajenju Jezusa Kristusa,',
        22: 'ki je po svojem vnebohodu na desnici Božji, in podrejeni so mu angeli in oblasti in moči.',
    },
    4: {
        1: 'Ker je torej Kristus trpel v mesu, oborožite se tudi vi z istim mišljenjem, ker kdor je trpel v mesu, je pri koncu z grehom:',
        2: 'da ne živite več človeškim slam, ampak volji Božji ostali čas v mesu.',
        3: 'Dosti namreč bodi pretekli čas življenja, ko ste delali voljo poganov, živeč v razuzdanosti, pohotnosti, pijanosti, požrešnosti, nezmernem popivanju in nespodobnem malikovanju;',
        4: 'zato se jim zdi čudno, da ne letate ž njimi v isto razuzdanost nezmernosti, in vas obrekujejo.',
        5: 'Ti bodo odgovor dajali njemu, ki je pripravljen soditi žive in mrtve.',
        6: 'Zato se je namreč tudi mrtvim oznanil evangelij, da bi bili sojeni po človeško v mesu, živeli pa bi po Božje v duhu.',
        7: 'Vsega konec pa se je približal. Bodite torej pametni in trezni za molitve;',
        8: 'predvsem pa imejte iskreno ljubezen med seboj, ker ljubezen pokriva grehov obilost.',
        9: 'Gostoljubni bodite med seboj brez godrnjanja.',
        10: 'Kakor je vsakteri prejel dar, služite si ž njim med seboj kot dobri oskrbniki mnogotere milosti Božje.',
        11: 'Če kdo govori, naj govori kakor izreke Božje; če kdo služi, naj služi kakor iz moči, ki jo deli Bog; da se v vsem oslavlja Bog po Jezusu Kristusu, ki mu je slava in moč na vekov veke. Amen.',
        12: 'Ljubljeni, nikar se ne čudite ognjenemu žaru, ki vas objemlje zaradi izkušnje, kakor da se vam godi kaj tujega,',
        13: 'temuč veselite se, v kolikor ste deležni trpljenja Kristusovega, da bi se tudi v razodetju slave njegove radovali z velikim veseljem.',
        14: 'Če vas psujejo zaradi imena Kristusovega, blagor vam; zakaj Duh slave in Duh Božji počiva nad vami.',
        15: 'Nihče izmed vas naj pa ne trpi kot morilec, ali tat, ali hudodelnik, ali kot tak, ki se meša v tuja opravila;',
        16: 'če pa trpi kot kristjan, ne bodi ga sram, a slavi naj Boga v tem imenu.',
        17: 'Kajti čas je, da se začne sodba pri hiši Božji: če pa najprej pri nas, kaj bo konec tistih, ki so neposlušni evangeliju Božjemu?',
        18: 'In če se iztežka reši pravični, kje ostane brezbožni in grešnik?',
        19: 'Zato naj tudi, kateri trpe po volji Božji, zvestemu stvarniku izročajo duše svoje, pridni v dobrih delih.',
    },
    5: {
        1: 'Starejšine med vami torej opominjam jaz, sostarejšina in priča trpljenja Kristusovega in tudi deležnik slave, ki se ima razodeti:',
        2: 'Pasite čredo Božjo, ki je pri vas, nadzorujoč jo ne po sili, ampak prostovoljno, po Bogu; tudi ne za grd dobiček, ampak radovoljno;',
        3: 'tudi ne kakor gospodovalci svoje posesti, temuč tako, da ste zgledi čredi.',
        4: 'In ko se prikaže višji Pastir, prejmete nevenljivi venec slave.',
        5: 'Enako mlajši, pokorite se starejšim; vsi pa si opašite ponižnost, da služite drug drugemu, ker „Bog se upira prevzetnim, ponižnim pa daje milost“.',
        6: 'Ponižajte se torej pod mogočno roko Božjo, da vas poviša ob času svojem;',
        7: 'vso skrb svojo zvrnite nanj, ker on skrbi za vas.',
        8: 'Bodite trezni, bedite: nasprotnik vaš, hudič, hodi kakor rjoveč lev okrog in išče, koga bi pogoltnil;',
        9: 'njemu se upirajte, trdni v veri, vedoč, da isto trpljenje prenaša bratovščina vaša razkropljena po svetu.',
        10: 'Bog vse milosti pa, ki vas je poklical v večno slavo svojo v Kristusu, vas sam po kratkem trpljenju napravi popolne, utrdi, pokrepča, ustanoviti.',
        11: 'Njemu moč na vekov veke! Amen.',
        12: 'Po Silvanu, zvestem bratu, kakor sodim, vam pišem na kratko, opominjajoč in pričajoč, da je ta prava milost Božja, v kateri stojite.',
        13: 'Pozdravlja vas cerkev, z vami izvoljena, ki je v Babilonu, in Marko, sin moj.',
        14: 'Pozdravljajte se med seboj s poljubom ljubezni! Mir vam vsem, ki ste v Kristusu!',
    },
}
